"use client";

import Link from "next/link";

import { navItems, ctaItem } from "@/config/navigation";

type MobileMenuProps = {
  open: boolean;
  onClose: () => void;
  menuId: string;
};

export function MobileMenu({ open, onClose, menuId }: MobileMenuProps) {
  return (
    <div
      id={menuId}
      role="dialog"
      aria-modal="true"
      aria-label="Mobile navigation"
      className={`fixed inset-0 z-40 lg:hidden ${
        open ? "pointer-events-auto" : "pointer-events-none"
      }`}
    >
      <div
        aria-hidden="true"
        onClick={onClose}
        className={`absolute inset-0 bg-ink/60 transition-opacity duration-200 ${
          open ? "opacity-100" : "opacity-0"
        }`}
      />

      <div
        className={`absolute inset-x-0 top-0 origin-top border-b-4 border-primary bg-background pb-10 pt-20 shadow-xl transition-transform duration-200 ease-out ${
          open ? "translate-y-0" : "-translate-y-full"
        }`}
      >
        <nav aria-label="Mobile primary" className="px-6">
          <ul className="flex flex-col divide-y-2 divide-border">
            {navItems.map((item) => (
              <li key={item.href}>
                <Link
                  href={item.href}
                  onClick={onClose}
                  className="block py-5 font-display text-2xl font-extrabold uppercase tracking-[0.04em] text-text transition-colors hover:text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-primary"
                >
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>

          <Link
            href={ctaItem.href}
            onClick={onClose}
            className="mt-8 inline-flex w-full items-center justify-center rounded-pill bg-accent px-6 py-4 font-display text-base font-extrabold uppercase tracking-[0.08em] text-ink transition hover:bg-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
          >
            {ctaItem.label}
          </Link>
        </nav>
      </div>
    </div>
  );
}
